-- Production starting schema; run with a migration identity, then use a restricted application role.
-- Requires PostgreSQL. Not used by the local SQLite reference service.
BEGIN;
CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL, timezone text NOT NULL, region text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE stores (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, timezone text NOT NULL, address text NOT NULL, config_version bigint NOT NULL DEFAULT 1, UNIQUE(org_id,id));
CREATE TABLE app_users (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), oidc_subject text NOT NULL, email text NOT NULL, role text NOT NULL CHECK(role IN ('viewer','responder','investigator','store_admin','org_admin')), active boolean NOT NULL DEFAULT true, UNIQUE(org_id,id), UNIQUE(org_id,oidc_subject));
CREATE TABLE memberships (org_id uuid NOT NULL, store_id uuid NOT NULL, user_id uuid NOT NULL, PRIMARY KEY(org_id,store_id,user_id), FOREIGN KEY(org_id,store_id) REFERENCES stores(org_id,id), FOREIGN KEY(org_id,user_id) REFERENCES app_users(org_id,id));
CREATE TABLE edges (id uuid PRIMARY KEY, org_id uuid NOT NULL, store_id uuid NOT NULL, certificate_fingerprint text UNIQUE NOT NULL, revoked_at timestamptz, config_version bigint NOT NULL DEFAULT 1, last_seen timestamptz, UNIQUE(org_id,id), UNIQUE(org_id,store_id,id), FOREIGN KEY(org_id,store_id) REFERENCES stores(org_id,id));
CREATE TABLE cameras (id uuid PRIMARY KEY, org_id uuid NOT NULL, store_id uuid NOT NULL, edge_id uuid NOT NULL, name text NOT NULL, credential_ref text NOT NULL, endpoint_uuid text, stream_profile text NOT NULL, readiness text NOT NULL CHECK(readiness IN ('pending','ready','degraded','offline','disabled')), config jsonb NOT NULL, version bigint NOT NULL DEFAULT 1, UNIQUE(org_id,id), UNIQUE(org_id,store_id,id), FOREIGN KEY(org_id,store_id) REFERENCES stores(org_id,id), FOREIGN KEY(org_id,store_id,edge_id) REFERENCES edges(org_id,store_id,id));
CREATE TABLE profiles (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), kind text NOT NULL CHECK(kind IN ('staff','watchlist')), reference text NOT NULL, display_name text NOT NULL, basis text NOT NULL, source_incident_id uuid, status text NOT NULL CHECK(status IN ('draft','pending_review','approved','suspended','expired','deleted')), approved_by uuid, expires_at timestamptz NOT NULL, review_at timestamptz NOT NULL, version bigint NOT NULL DEFAULT 1, UNIQUE(org_id,id), UNIQUE(org_id,kind,reference), FOREIGN KEY(org_id,approved_by) REFERENCES app_users(org_id,id));
CREATE TABLE profile_scopes (org_id uuid NOT NULL, profile_id uuid NOT NULL, store_id uuid NOT NULL, PRIMARY KEY(org_id,profile_id,store_id), FOREIGN KEY(org_id,profile_id) REFERENCES profiles(org_id,id), FOREIGN KEY(org_id,store_id) REFERENCES stores(org_id,id));
CREATE TABLE media (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), store_id uuid, storage_key text UNIQUE NOT NULL, sha256 text NOT NULL CHECK(length(sha256)=64), mime text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes>0), expires_at timestamptz NOT NULL, hold_reason text, hold_review_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,id), FOREIGN KEY(org_id,store_id) REFERENCES stores(org_id,id));
CREATE TABLE profile_photos (id uuid PRIMARY KEY, org_id uuid NOT NULL, profile_id uuid NOT NULL, media_id uuid NOT NULL, quality jsonb NOT NULL, provenance jsonb NOT NULL, status text NOT NULL CHECK(status IN ('pending','approved','rejected','deleted')), UNIQUE(org_id,id), FOREIGN KEY(org_id,profile_id) REFERENCES profiles(org_id,id), FOREIGN KEY(org_id,media_id) REFERENCES media(org_id,id));
CREATE TABLE face_templates (id uuid PRIMARY KEY, org_id uuid NOT NULL, profile_id uuid NOT NULL, photo_id uuid NOT NULL, encrypted_key text NOT NULL, sdk_version text NOT NULL, template_format text NOT NULL, gallery_revision bigint NOT NULL, UNIQUE(org_id,id), FOREIGN KEY(org_id,profile_id) REFERENCES profiles(org_id,id), FOREIGN KEY(org_id,photo_id) REFERENCES profile_photos(org_id,id));
CREATE TABLE incidents (id uuid PRIMARY KEY, org_id uuid NOT NULL, store_id uuid NOT NULL, camera_id uuid NOT NULL, event_id text NOT NULL, channel text NOT NULL CHECK(channel IN ('behavior_candidate','watchlist_candidate','checkout_exception','rfid_exception','manual_observation')), status text NOT NULL CHECK(status IN ('new','acknowledged','reviewing','resolved')), outcome text CHECK(outcome IN ('confirmed','false_alert','inconclusive')), assignee uuid, version bigint NOT NULL DEFAULT 1, captured_at timestamptz NOT NULL, ingested_at timestamptz NOT NULL DEFAULT now(), signals jsonb NOT NULL, evidence_state text NOT NULL CHECK(evidence_state IN ('pending','available','unavailable','expired')), model_version text NOT NULL, UNIQUE(org_id,id), UNIQUE(org_id,event_id), FOREIGN KEY(org_id,store_id) REFERENCES stores(org_id,id), FOREIGN KEY(org_id,store_id,camera_id) REFERENCES cameras(org_id,store_id,id), FOREIGN KEY(org_id,assignee) REFERENCES app_users(org_id,id), CHECK(status<>'resolved' OR outcome IS NOT NULL));
ALTER TABLE profiles ADD CONSTRAINT source_incident_fk FOREIGN KEY(org_id,source_incident_id) REFERENCES incidents(org_id,id);
CREATE TABLE incident_evidence (org_id uuid NOT NULL, incident_id uuid NOT NULL, media_id uuid NOT NULL, PRIMARY KEY(org_id,incident_id,media_id), FOREIGN KEY(org_id,incident_id) REFERENCES incidents(org_id,id), FOREIGN KEY(org_id,media_id) REFERENCES media(org_id,id));
CREATE TABLE reviews (id uuid PRIMARY KEY, org_id uuid NOT NULL, incident_id uuid NOT NULL, actor_id uuid NOT NULL, reason text NOT NULL CHECK(length(reason)>0), outcome text CHECK(outcome IN ('confirmed','false_alert','inconclusive')), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(org_id,incident_id) REFERENCES incidents(org_id,id), FOREIGN KEY(org_id,actor_id) REFERENCES app_users(org_id,id));
CREATE TABLE cases (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), owner_id uuid NOT NULL, title text NOT NULL, status text NOT NULL CHECK(status IN ('open','closed')), version bigint NOT NULL DEFAULT 1, UNIQUE(org_id,id), FOREIGN KEY(org_id,owner_id) REFERENCES app_users(org_id,id));
CREATE TABLE case_incidents (org_id uuid NOT NULL, case_id uuid NOT NULL, incident_id uuid NOT NULL, PRIMARY KEY(org_id,case_id,incident_id), FOREIGN KEY(org_id,case_id) REFERENCES cases(org_id,id), FOREIGN KEY(org_id,incident_id) REFERENCES incidents(org_id,id));
CREATE TABLE audit (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), actor_id uuid, action text NOT NULL, resource_id text NOT NULL, detail jsonb NOT NULL, request_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), event_key text NOT NULL, topic text NOT NULL, payload jsonb NOT NULL, attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz, UNIQUE(org_id,event_key,topic));
CREATE TABLE push_devices (id uuid PRIMARY KEY, org_id uuid NOT NULL, user_id uuid NOT NULL, token_ciphertext text NOT NULL, environment text NOT NULL CHECK(environment IN ('sandbox','production')), bundle_id text NOT NULL, revoked_at timestamptz, FOREIGN KEY(org_id,user_id) REFERENCES app_users(org_id,id));
CREATE INDEX incidents_store_time ON incidents(org_id,store_id,captured_at DESC,id);
CREATE INDEX profiles_active ON profiles(org_id,kind,status,expires_at);
CREATE INDEX outbox_pending ON outbox(available_at) WHERE delivered_at IS NULL;
CREATE INDEX audit_org_time ON audit(org_id,created_at DESC);
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE organizations FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON organizations USING (id = NULLIF(current_setting('app.org_id',true),'')::uuid) WITH CHECK (id = NULLIF(current_setting('app.org_id',true),'')::uuid);
-- Tenant RLS defense in depth. Store/action authorization must also be enforced by the API.
DO $$ DECLARE n text; BEGIN
FOREACH n IN ARRAY ARRAY['stores','app_users','memberships','edges','cameras','profiles','profile_scopes','media','profile_photos','face_templates','incidents','incident_evidence','reviews','cases','case_incidents','audit','outbox','push_devices'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',n);
  EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',n);
  EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (org_id = NULLIF(current_setting(''app.org_id'',true),'''')::uuid) WITH CHECK (org_id = NULLIF(current_setting(''app.org_id'',true),'''')::uuid)',n);
END LOOP;
END $$;
COMMIT;
